import React from 'react';

type LayoutVariant = 'full-width' | 'centered';

type LayoutProps = {
  children: React.ReactNode;
  variant?: LayoutVariant;
  className?: string;
  data?: Record<string, unknown>;
};

function Layout({ children, variant = 'centered', className, data }: LayoutProps) {
  const baseClass = {
    base:
      'w-full min-h-screen bg-white dark:bg-gray-800',
    container:
      'max-w-7xl mx-auto px-4 sm:px-6 lg:px-8',
    fullContainer:
      'w-full py-0',
  };

  const variantClasses = variant === 'full-width' ? baseClass.fullContainer : baseClass.container;

  return (
    <div
      className={`${baseClass.base} ${variantClasses} ${className ?? ''}`}
      data-variant={variant}
      {...data}
    >
      {children}
    </div>
  );
}

export type { LayoutVariant, LayoutProps };
export default Layout;
```

